-- 테이블 ipforce.PROJECT_DATA_TB 구조 내보내기
CREATE TABLE IF NOT EXISTS `PROJECT_DATA_TB` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) DEFAULT NULL COMMENT '유저 고유번호',
  `project_id` int(11) DEFAULT NULL,
  `source_type` enum('DB','FILE','search','upload') NOT NULL COMMENT '프로젝트 종류',
  `project_code` tinytext NOT NULL COMMENT '프로젝트 고유번호',
  `collection_id` int(11) DEFAULT NULL,
  `collection_code` tinytext DEFAULT NULL COMMENT '카테고리 고유번호',
  `collection_name` tinytext DEFAULT NULL COMMENT '카테고리(class)',
  `title` text NOT NULL COMMENT '특허명',
  `abstract` text NOT NULL COMMENT '특허 요약문',
  `used` tinyint(4) DEFAULT NULL COMMENT '사용여부',
  `applicant_name` text DEFAULT NULL COMMENT '출원인 또는 발명자(inventor)',
  `applicant_code` varchar(100) DEFAULT NULL,
  `application_number` bigint(13) unsigned DEFAULT NULL COMMENT '출원번호',
  `application_date` date DEFAULT NULL COMMENT '출원날짜(filling date)',
  `grand_status` tinyint(4) DEFAULT NULL COMMENT '출원상태',
  `ipc_code` text DEFAULT NULL COMMENT 'IPC 코드',
  `cpc_code` text DEFAULT NULL COMMENT 'CPC 코드',
  `probability` float DEFAULT NULL,
  `created_datetime` datetime DEFAULT NULL COMMENT '최초 등록 날짜',
  `updated_datetime` datetime DEFAULT NULL COMMENT '마지막 수정 날짜',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `IDX__APPLICATION_NUMBER` (`application_number`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=157061 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='bibliography_dump';

